const body = $input.first().json.body || $input.first().json;
const mode = body.mode || 'B';
const brief = String(body.brief || '').trim();
const targetStack = body.targetStack || 'react-vite';
const referenceUrl = body.referenceUrl || null;
if (!brief) throw new Error('brief is required');
return [{ json: { mode, brief, targetStack, referenceUrl } }];

// P1: build a 1-reference baseline by hand-rolling the merge.
// P2 replaces this with `node scripts/build-baseline.mjs`.
const hasRef = Boolean($('parse').item.json.referenceUrl);
const scrapeItem = $('Scrape reference').first().json || {};
const fp = scrapeItem.fingerprint || null;
if (!fp) {
  throw new Error('P1 requires a referenceUrl; search-only path is P2');
}
const baseline = {
  version: 1,
  createdAt: new Date().toISOString(),
  sourceFingerprints: [fp.sourceUrl],
  palette: fp.palette.map(p => p.hex),
  fonts: fp.fonts.map(f => f.family),
  motion: fp.motion,
  components: fp.components,
};
return [{ json: { baseline, fingerprint: fp, brief: $('parse').item.json.brief, targetStack: $('parse').item.json.targetStack } }];

