const out = $('Generate (Ollama)').first().json;
const txt = out.choices?.[0]?.message?.content || '';
let parsed = null;
try { parsed = JSON.parse(txt); } catch {}
return [{ json: { ok: Boolean(parsed), files: parsed?.files || [], notes: parsed?.notes || '', raw: txt, baseline: $('Build baseline').item.json.baseline, fingerprint: $('Build baseline').item.json.fingerprint } }];
